// th14_s7_b18 — TH14 v1.00b st07bs.ecl Boss10 (135-174) -> BossCard10 (997-1108).
// spellEx 119「プリスティンビート」, source !O -> rank 4 only.
// card frame 0 = Boss10 entry; native spell clock 0 = BossCard10's timerReset (~card frame 120).

const TIME_LIMIT: int = 7744;      // 120 wrapper + 7200 native + tail budget
const SPELL_ID: int = 119;
const SPELL_BONUS: int = 500000;   // spellEx third field
const SPELL_TIME: int = 7200;      // spellEx(119, $A*60), $A = 120
const PHASE_TIMEOUT: int = 5400;   // source ($A-30)*60 internal fallback

// Enemy shared slots owned by this card:
//   int0 = source $I0 (bullet colour)   int1 = moveRand step counter
//   int3 = emit phase gate (source killAsync(0/1))
//   fx0/fx1 = moveRand logical direction (cos, sin)

// ---- moveRand(60, 0, 0.6) + moveLimit(0,128,280,64), source 1130/1180/1220 ----
// Shared recipe (th16/movement.md): direction is sampled once per call, speed is the
// logical scalar 0.6*(1-k/60), position is clamped to x[-140,140] y[96,160] per frame,
// and the source's move->ECL order is emulated by arming the next step during ECL.
sub arm_next_step() {
    var k: int = self_int(1) + 1;
    set_self_int(1, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 0.6fx * ((60 - k) as fx / 60); }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub begin_dir(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(1, 0);
    arm_next_step();
}

sub move_rand() {
    // source 412: signed uniform angle * pi, x<-70 / x>70 / central branch, y 112..144
    // fabs fixup, then the native +-pi/2 guard (0.05 rad ~= 522 BAM).
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_dir(a as angle);
}

// Per-frame waits for the emitting task: stop when the source killAsync point hit,
// and keep the source movement stepping (only the driving task may call the arm helper).
sub emit_wait(ph: int, n: int) {
    for i in 0..n {
        if self_int(3) != ph { return; }
        wait(1);
        arm_next_step();
    }
}

// Parallel async emitter / non-driving waits: same stop gate, movement not armed.
sub emit_wait_plain(ph: int, n: int) {
    for i in 0..n {
        if self_int(3) != ph { return; }
        wait(1);
    }
}

sub w(arm: int, ph: int, n: int) {
    if arm != 0 { emit_wait(ph, n); } else { emit_wait_plain(ph, n); }
}

// ---- emitters (etNew/etAim/etSprite/etCount/etAngle/etSpeed/etEx/etDist/etOn) ----

// BossCard10_beat1 (1247-1259): 52-way aimed half-offset ring, speed 4.5,
// type42/colour6, etEx ANIM a=1 back-off 4*4.5=18, etDist 32 -> net 14.
sub beat1() {
    sh_reset(0);
    sh_sprite(0, TH14_REST, 6);
    sh_ring(0, 1);
    sh_aim(0, 1);
    sh_count(0, 52, 1);
    sh_speed(0, 4.5fx, 0fx);
    sh_angle(0, (32768 / 52) as angle, 0deg);
    sh_dist(0, 14fx);
    sh_fire(0);
}

// BossCard10_beat2/beat2b (1261-1289): aim mode 10, N ways x 3 layers, speeds
// 2.0/1.9/1.9, type8 colour $I0, one %RANDRAD base per wave, etOffset (ox,oy).
// mode10 layers: q0 = alpha+(R(i)+H), q1/q2 = alpha-(R(i)+delta) and H=delta for both,
// so q1/q2 are one duplicated ring; the mirrored ring is expressed as the same point
// set of a +ring (creation-order only difference, no consumer).
sub beat2_n(n: int, ox: fx, oy: fx) {
    var base: int = rand(65536) - 32768;
    sh_reset(1);
    sh_sprite(1, TH14_RICE, self_int(0));
    sh_ring(1, 1);
    sh_aim(1, 0);
    sh_count(1, n, 1);
    sh_speed(1, 2fx, 0fx);
    sh_angle(1, base as angle, 0deg);
    sh_offset(1, ox, oy);
    sh_dist(1, -8fx);
    sh_fire(1);
    sh_reset(2);
    sh_sprite(2, TH14_RICE, self_int(0));
    sh_ring(2, 1);
    sh_aim(2, 0);
    sh_count(2, n, 2);
    sh_speed(2, 1.9fx, 0fx);
    sh_angle(2, (base - 91) as angle, 0deg);
    sh_offset(2, ox, oy);
    sh_dist(2, -7.6fx);
    sh_fire(2);
}

// BossCard10_beat3 (1291-1304): 36-way aimed ring, speed 3.0, type39 colour 0,
// ANIM back-off 4*3=12, etDist 32 -> net 20.
sub beat3() {
    sh_reset(0);
    sh_sprite(0, TH14_NOTE_BLUE, 0);
    sh_ring(0, 1);
    sh_aim(0, 1);
    sh_count(0, 36, 1);
    sh_speed(0, 3fx, 0fx);
    sh_angle(0, 0deg, 0deg);
    sh_dist(0, 20fx);
    sh_fire(0);
}

