sub at3b_body(arm: int, ph: int) {
    w(arm, ph, 22);
    if self_int(3) != ph { return; }
    beat2_n(32, 32fx, 0fx);
    w(arm, ph, 23);
    if self_int(3) != ph { return; }
    beat2_n(32, -32fx, 0fx);
    w(arm, ph, 11);
    if self_int(3) != ph { return; }
    beat2_n(32, 64fx, -32fx);
    w(arm, ph, 11);
    if self_int(3) != ph { return; }
    beat2_n(32, -64fx, -32fx);
    w(arm, ph, 12);
    if self_int(3) != ph { return; }
    beat2_n(32, 0fx, 32fx);
    w(arm, ph, 11);
}

sub at4b_body(arm: int, ph: int) {
    w(arm, ph, 22);
    if self_int(3) != ph { return; }
    beat2_n(25, 64fx, 0fx);
    w(arm, ph, 11);
    if self_int(3) != ph { return; }
    beat2_n(25, -64fx, 0fx);
    w(arm, ph, 12);
    w(arm, ph, 11);
    if self_int(3) != ph { return; }
    beat2_n(25, 32fx, -32fx);
    w(arm, ph, 6);
    if self_int(3) != ph { return; }
    beat2_n(25, -32fx, -32fx);
    w(arm, ph, 6);
    if self_int(3) != ph { return; }
    beat2_n(25, 96fx, -32fx);
    w(arm, ph, 11);
    if self_int(3) != ph { return; }
    beat2_n(25, -96fx, -32fx);
    w(arm, ph, 11);
    if self_int(3) != ph { return; }
    beat2_n(25, 0fx, 32fx);
}

async sub at3b_async(ph: int) {
    at3b_body(0, ph);
}

async sub at4b_async(ph: int) {
    at4b_body(0, ph);
}

// ---- async emitters = source async 0 (at / at2 / at3 / at4) ----

// BossCard10_at (1110-1134): $I0=6, 90 | beat1 | 45 | beat2 x2 | 45 | beat2 | moveRand
async sub at_emitter(ph: int) {
    set_self_int(0, 6);
    loop {
        emit_wait(ph, 90);
        if self_int(3) != ph { return; }
        beat1();
        emit_wait(ph, 45);
        if self_int(3) != ph { return; }
        beat2_n(32, 32fx, 0fx);
        beat2_n(32, -32fx, 0fx);
        emit_wait(ph, 45);
        if self_int(3) != ph { return; }
        beat2_n(32, 0fx, 32fx);
        move_rand();
    }
}

