// BossCard10_at3 (1164-1184): $I0=2, 90 | beat1 | at3b sync (async id 1 spawn after)
// | moveRand. at3b occupies 90 frames, so the async copy starts at the loop tail.
async sub at3_emitter(ph: int) {
