// ---- spell pattern: BossCard10 phase machine (1002-1108) ----

async sub card_pattern() {
    // 1018 movePosTime(60,4,0,144)
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    // 1025 "+60": at (async 0) starts at native 60
    wait(60);

    // 1030-1037: until LIFE<6200 or TIME>=5400
    set_self_int(3, 1);
    spawn at_emitter(1);
    while $self_hp >= 6200 && $self_age < PHASE_TIMEOUT { wait(1); }
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    if $self_age < PHASE_TIMEOUT { wait(60); }

    // 1044-1053: until LIFE<4400 or TIME>=5400
    set_self_int(3, 2);
    spawn at2_emitter(2);
    while $self_hp >= 4400 && $self_age < PHASE_TIMEOUT { wait(1); }
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    if $self_age < PHASE_TIMEOUT { wait(60); }

    // 1061-1072: until LIFE<2600 or TIME>=5400, GI0++ per surviving frame
    var gi0: int = 0;
    set_self_int(3, 3);
    spawn at3_emitter(3);
    while $self_hp >= 2600 && $self_age < PHASE_TIMEOUT {
        gi0 = gi0 + 1;
        wait(1);
    }
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    if $self_age < PHASE_TIMEOUT { wait(60); }

    // 1080-1091: until LIFE<800 or TIME>=5400, GI0 reset then ++ per surviving frame
    gi0 = 0;
    set_self_int(3, 4);
    spawn at4_emitter(4);
    while $self_hp >= 800 && $self_age < PHASE_TIMEOUT {
        gi0 = gi0 + 1;
        wait(1);
    }
    set_self_int(3, 5);
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    if $self_age < PHASE_TIMEOUT { wait(60); }

    // 1093-1101: beat3 whenever GI0%45==22; source stops emitting at the 7200 interrupt
    while $self_age < SPELL_TIME {
        if gi0 % 45 == 22 { beat3(); }
        gi0 = gi0 + 1;
        wait(1);
    }
    // source setInterrupt(0,0,7200,"BossDead"): attack ends here, no next attack.
    // Remaining card window is tail budget only.
    while $self_age < TIME_LIMIT { wait(1); }
}

// ---- boss shell ----

sub boss_card10() {
    // 1002 timerReset -> pattern birth is the native clock 0.
    // 1017 spellEx(119, 7200, 500000); hp gate 800 = lowest source LIFE marker.
    spell_begin(0, SPELL_ID, card_pattern, SPELL_TIME, SPELL_BONUS, 0, 800);
}

async sub boss_main() {
    // Shell: undamageable boss carrying the source body box (Boss() 48/48 -> r=24).
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(24fx);
    // Idle moveRand state: no residual step until the first source moveRand.
    set_self_int(1, 60);
    set_self_fx(0, 1fx);
    set_self_fx(1, 0fx);
    set_self_int(0, 0);
    set_self_int(3, 0);

    // Boss10 141-171: entry transition, then the explicit 120-frame break.
    clear_bullets_at($self_x, $self_y, 640fx, 0);          // 153 etCancel(640) entry clear
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);                // 168 movePosTime(60,4,0,128)
    wait(120);                                             // 169-171 setInvuln(120)+wait(120)
    boss_card10();
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 8000, 0, 0, 0, boss_main);
    loop { wait(600); }
}

